import{_ as n,o as e,c as i,ae as t}from"./chunks/framework.CFyvOAXl.js";const g=JSON.parse('{"title":"AI Infra 面试 Wiki · 导读","description":"","frontmatter":{},"headers":[],"relativePath":"program/interview/aiinfra_overview.md","filePath":"program/interview/aiinfra_overview.md","lastUpdated":1786894185000}'),r={name:"program/interview/aiinfra_overview.md"};function s(o,a,l,h,c,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="ai-infra-面试-wiki-·-导读" tabindex="-1">AI Infra 面试 Wiki · 导读 <a class="header-anchor" href="#ai-infra-面试-wiki-·-导读" aria-label="Permalink to &quot;AI Infra 面试 Wiki · 导读&quot;">​</a></h1><blockquote><p>首次编写：2026-08-12 | 最后更新：2026-08-12</p></blockquote><blockquote><p><strong>AI Infra / KV Cache 面试系列</strong></p><ul><li><strong>导读（本页）</strong> ← 当前文章</li><li><a href="./aiinfra_jobs.html">招聘岗位全景</a></li><li><a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a></li><li><a href="./aiinfra_interview_questions.html">面经与高频考点</a></li><li><a href="./aiinfra_system_design.html">系统设计专题</a></li><li><a href="./aiinfra_2month_plan.html">2 个月面试复习计划</a></li><li><a href="./aiinfra_resources.html">资源汇总</a></li></ul></blockquote><hr><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>这是一份面向 <strong>AI Infra（AI 基础设施）方向，尤其聚焦 KV Cache 与大模型推理系统</strong> 的面试准备 Wiki。覆盖三件事：</p><ol><li><strong>招聘岗位全景</strong>：哪些公司在招、岗位类型划分、JD 拆解、职级与能力要求。</li><li><strong>面经与高频考点</strong>：按主题归类的题库 + 参考答题思路，覆盖 KV Cache、推理引擎、分布式与通信、系统设计、Coding。</li><li><strong>2 个月复习计划</strong>：周粒度的可执行计划，把上面两块串成一条复习主线。</li></ol><h2 id="为什么以-kv-cache-为锚点" tabindex="-1">为什么以 KV Cache 为锚点 <a class="header-anchor" href="#为什么以-kv-cache-为锚点" aria-label="Permalink to &quot;为什么以 KV Cache 为锚点&quot;">​</a></h2><p>KV Cache 是大模型推理系统里<strong>最集中体现&quot;系统 + 算法 + 硬件&quot;交叉</strong>的子系统：</p><ul><li>它是<strong>显存瓶颈</strong>：推理时显存占用的大头往往不是权重而是 KV Cache，长上下文场景下尤为突出。</li><li>它是<strong>吞吐瓶颈</strong>：Decode 阶段是 memory-bound，KV Cache 的访存效率直接决定 token/s。</li><li>它是<strong>优化富矿</strong>：PagedAttention、RadixAttention、MLA、前缀复用、量化、卸载、分离式推理……近两年几乎所有有影响力的推理工作都围绕它展开。</li><li>它是<strong>面试富矿</strong>：因为它既考&quot;为什么&quot;（自回归、attention 计算）、又考&quot;怎么算&quot;（显存公式）、又考&quot;怎么工程&quot;（分页、调度、池化），一面能区分候选人的系统功底。</li></ul><p>因此本 Wiki 把 KV Cache 作为主线，向外辐射到推理引擎、注意力内核、批处理调度、分布式通信与系统设计。</p><h2 id="关于信息来源的说明-重要" tabindex="-1">关于信息来源的说明（重要） <a class="header-anchor" href="#关于信息来源的说明-重要" aria-label="Permalink to &quot;关于信息来源的说明（重要）&quot;">​</a></h2><blockquote><p>本 Wiki 撰写于 2026-08-12。环境中的 <strong>WebSearch / WebFetch 工具被策略阻断</strong>，但通过 <strong>Bash curl 实测</strong>，arxiv.org、github.com、nowcoder.com（牛客）、vllm.ai、sglang 文档等域名<strong>可达</strong>，google/huggingface 不可达。据此做了真实抓取：</p><ul><li><strong>论文链接</strong>：<a href="./aiinfra_resources.html">资源汇总</a> 中 20+ 篇 arXiv 链接均经 curl 逐一核实标题与可达性。</li><li><strong>面经</strong>：<a href="./aiinfra_interview_questions.html">题库第 7.0 节</a> 为实时抓取自牛客的真实面经帖（含 2026 校招快手 AI Infra、美团北斗、华为海思等），链接已核实。</li><li><strong>招聘岗位的&quot;具体 JD/薪资&quot;</strong>：Boss 直聘/拉勾等需登录、JS 渲染，curl 抓不到有效内容，仍为<strong>结构化盘点</strong>，需你用实时渠道补全（见各页&quot;待补全&quot;清单）。</li><li><strong>技术知识体系、复习计划、题库答题思路</strong>：基于该领域公开稳定知识整理，可作复习骨架。</li></ul><p>简言之：<strong>论文与面经已是真链接，JD/薪资仍需你补</strong>。本 Wiki 给地图和训练方法，实时赛况部分已替你刷过一轮。</p></blockquote><h2 id="怎么用这份-wiki" tabindex="-1">怎么用这份 Wiki <a class="header-anchor" href="#怎么用这份-wiki" aria-label="Permalink to &quot;怎么用这份 Wiki&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的状态</th><th>建议路径</th></tr></thead><tbody><tr><td>刚转方向 / 基础薄弱</td><td>导读 → <a href="./aiinfra_jobs.html">招聘全景</a>（知道要学什么）→ <a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a>（打地基）→ <a href="./aiinfra_2month_plan.html">2 个月计划</a></td></tr><tr><td>有一定基础，临近面试</td><td><a href="./aiinfra_interview_questions.html">面经与高频考点</a>（查漏补缺）→ <a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a>（深挖重点）→ 计划里的&quot;冲刺周&quot;</td></tr><tr><td>已有 offer，想横向比较</td><td><a href="./aiinfra_jobs.html">招聘全景</a> 的职级/薪资/团队盘点</td></tr></tbody></table><h2 id="岗位方向速览-详见-招聘全景" tabindex="-1">岗位方向速览（详见 <a href="./aiinfra_jobs.html">招聘全景</a>） <a class="header-anchor" href="#岗位方向速览-详见-招聘全景" aria-label="Permalink to &quot;岗位方向速览（详见 [招聘全景](aiinfra_jobs.md)）&quot;">​</a></h2><p>AI Infra 是个筐，不同公司拆法不同，但大致可归为五类：</p><ol><li><strong>推理系统 / Serving</strong>：推理引擎、调度、KV Cache 管理、批处理。<strong>KV Cache 方向的主战场。</strong></li><li><strong>训练框架 / 分布式</strong>：Megatron / DeepSpeed 类，TP/PP/EP/CP，通信优化。</li><li><strong>算子 / Kernel</strong>：CUDA、Triton、FlashAttention 类融合算子、量化算子。</li><li><strong>硬件 / 编译</strong>：算子库（cuBLAS/cutlass）、图编译（TensorRT, XLA, TorchInductor）、芯片侧。</li><li><strong>平台 / 工程化</strong>：大集群调度、容错、监控、多租户、成本。</li></ol><p>KV Cache 最常出现在 <strong>1 和 3</strong>，其次是 <strong>5</strong>（分离式推理池化、多租户 KV 隔离）。</p><h2 id="核心知识地图-详见-kv-cache-核心知识体系" tabindex="-1">核心知识地图（详见 <a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a>） <a class="header-anchor" href="#核心知识地图-详见-kv-cache-核心知识体系" aria-label="Permalink to &quot;核心知识地图（详见 [KV Cache 核心知识体系](aiinfra_kvcache_deep_dive.md)）&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        KV Cache</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>   ┌───────────┬───────────┼───────────┬──────────────┬──────────────┐</span></span>
<span class="line"><span>   ▼           ▼           ▼           ▼              ▼              ▼</span></span>
<span class="line"><span> 为什么需要    显存建模     存储管理     压缩/减少       复用/共享       生命周期</span></span>
<span class="line"><span> 自回归解码    占用公式     PagedAttention  GQA/MQA/MLA   RadixAttention  驱逐/卸载/池化</span></span>
<span class="line"><span>              显存瓶颈     连续批处理     量化           前缀缓存        sliding window</span></span>
<span class="line"><span>                          chunked prefill                cross-request   StreamingLLM</span></span>
<span class="line"><span>                          分离式推理                     复用            Mooncake 池化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="复习计划速览-详见-2-个月计划" tabindex="-1">复习计划速览（详见 <a href="./aiinfra_2month_plan.html">2 个月计划</a>） <a class="header-anchor" href="#复习计划速览-详见-2-个月计划" aria-label="Permalink to &quot;复习计划速览（详见 [2 个月计划](aiinfra_2month_plan.md)）&quot;">​</a></h2><ul><li><strong>第 1–2 周</strong>：地基。Transformer/Attention 推导 + KV Cache 显存建模 + CUDA 基础。</li><li><strong>第 3–4 周</strong>：推理引擎。vLLM / SGLang / TRT-LLM 源码与设计，PagedAttention、连续批处理。</li><li><strong>第 5–6 周</strong>：KV Cache 深水区。MLA、RadixAttention、量化、卸载、分离式推理（DistServe/Splitwise/Mooncake）。</li><li><strong>第 7 周</strong>：分布式 + 算子。TP/PP/EP/CP、NCCL、FlashAttention、量化算子。</li><li><strong>第 8 周</strong>：系统设计 + 面经冲刺 + 模拟面试。</li></ul><h2 id="阅读约定" tabindex="-1">阅读约定 <a class="header-anchor" href="#阅读约定" aria-label="Permalink to &quot;阅读约定&quot;">​</a></h2><ul><li>公式中 <code>L</code>=层数，<code>n_kv</code>=KV 头数，<code>d_h</code>=每头维度，<code>s</code>=序列长度，<code>b</code>=batch，<code>p</code>=每元素字节数。</li><li>&quot;高频⭐&quot;标注表示该知识点在面经中反复出现。</li><li>标注 ❓ 的为开放题 / 有争议题，需结合最新进展判断。</li></ul>`,25)])])}const u=n(r,[["render",s]]);export{g as __pageData,u as default};
